import{_ as t,a as o,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Verify Customer Token","description":"","frontmatter":{"outline":false,"examples":[{"id":"customer-verify-token","title":"Verify Customer Token","description":"Verify if the customer authentication token is still valid.","request":"POST /api/shop/verify-tokens\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"id\\": 1821,\\n  \\"firstName\\": \\"Doc\\",\\n  \\"lastName\\": \\"Check\\",\\n  \\"email\\": \\"doc.check@example.com\\",\\n  \\"isValid\\": true,\\n  \\"message\\": \\"Token is valid\\"\\n}\\n","commonErrors":[{"error":"isValid false with the message \\"Unauthenticated. Please login to perform this action\\"","cause":"The token is unknown, revoked by a logout, or no Authorization header was sent","solution":"Send the customer back through login and store the fresh token"},{"error":"401 Unauthorized","cause":"The storefront key header is missing","solution":"Send X-STOREFRONT-KEY on the request"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customers/customer-verify-token.md","filePath":"api/rest-api/shop/customers/customer-verify-token.md","lastUpdated":1786429091000}'),r={name:"api/rest-api/shop/customers/customer-verify-token.md"};function i(n,e,d,c,h,l){return a(),o("div",null,e[0]||(e[0]=[s('<h1 id="verify-customer-token" tabindex="-1">Verify Customer Token <a class="header-anchor" href="#verify-customer-token" aria-label="Permalink to &quot;Verify Customer Token&quot;">​</a></h1><p>Verify if the customer authentication token is still valid and retrieve customer information.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/verify-tokens</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token to verify</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p>The endpoint always answers <code>201 Created</code>, whether the token checks out or not. Read <code>isValid</code> — never the status code.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Customer ID when the token is valid, <code>0</code> when it is not.</td></tr><tr><td><code>firstName</code> / <code>lastName</code></td><td>string</td><td>Name of the token&#39;s owner, empty strings when the token is invalid.</td></tr><tr><td><code>email</code></td><td>string</td><td>Email of the token&#39;s owner, empty string when the token is invalid.</td></tr><tr><td><code>isValid</code></td><td>boolean</td><td>Whether the token resolves to a live customer.</td></tr><tr><td><code>message</code></td><td>string</td><td><code>Token is valid</code>, or <code>Unauthenticated. Please login to perform this action</code>.</td></tr></tbody></table><p>An unknown token, a token revoked by <a href="/api/rest-api/shop/customers/customer-logout.html">logout</a>, and a request with no <code>Authorization</code> header all produce the same invalid response — the endpoint does not distinguish them.</p><h2 id="token-lifetime" tabindex="-1">Token Lifetime <a class="header-anchor" href="#token-lifetime" aria-label="Permalink to &quot;Token Lifetime&quot;">​</a></h2><p>Customer tokens do not carry an expiry of their own. A token stays usable until it is revoked, which happens when the customer logs out with it or their account is deleted. There is no refresh endpoint: replace a dead token by logging in again.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Resume a session on app start</strong> — call once with the stored token and use <code>isValid</code> to decide between the logged-in and logged-out shell, instead of waiting for the first real request to fail.</li><li><strong>Re-hydrate the header from one call</strong> — a valid response carries the customer&#39;s name and email, enough to render an account header without a follow-up profile fetch.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Branch on <code>isValid</code>, not on HTTP status</strong> — every outcome is <code>201</code>, so status-code checks read every invalid token as a success.</li><li><strong>Do not call it before every request</strong> — it is a session-resume check; the endpoint the client actually wants already answers <code>401</code> when the token is dead.</li><li><strong>Discard the stored token as soon as <code>isValid</code> is false</strong> — nothing about it will start working again.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> — authenticate and receive a customer token</li><li><a href="/api/rest-api/shop/customers/customer-logout.html">Customer Logout</a> — revoke the token used on the request</li><li><a href="/api/rest-api/shop/customers/customer-registration.html">Customer Registration</a> — create an account and receive a token</li></ul>',18)]))}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
